@namespace sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Components.Pages.Settings
@using sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Services

<div class="section-panel">
    <h3>Profile</h3>
    <p class="text-muted">Manage your personal information</p>
    <hr />

    @if (Profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="Email" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="Bio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="avatar-preview text-center">
                    <label class="form-label fw-semibold">Avatar Preview</label>
                    <div class="avatar-frame mb-2">
                        <img src="@AvatarUrl" alt="Avatar" class="avatar-img" />
                    </div>
                    <input type="text" class="form-control form-control-sm" placeholder="Avatar URL"
                           @bind="AvatarUrl" />
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync">
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">
                Discard Changes
            </button>
        </div>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert @_statusCss mt-3 d-flex align-items-center" role="alert">
                @_statusMessage
            </div>
        }
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string Bio = "";
    private string AvatarUrl = "";

    private string? _statusMessage;
    private string _statusCss = "alert-success";

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(DisplayName) && !_initialized)
        {
            LoadFromProfile();
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        Bio = Profile.Bio;
        AvatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "✓ Profile saved successfully!";
        _statusCss = "alert-success";
    }

    private void Discard()
    {
        LoadFromProfile();
        _statusMessage = "Changes discarded.";
        _statusCss = "alert-info";
    }
}

.section-panel {
    padding: 0.5rem 0;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    margin: 0 auto;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    background-color: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

@namespace sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Components.Pages.Settings
@using sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Services

<div class="section-panel">
    <h3>Notifications</h3>
    <p class="text-muted">Choose how you want to be notified</p>
    <hr />

    @if (Prefs is not null)
    {
        <div class="mb-4">
            <h5>General</h5>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@EmailNotifications"
                       @onchange="e => EmailNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@PushNotifications"
                       @onchange="e => PushNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@WeeklyDigest"
                       @onchange="e => WeeklyDigest = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h5>Muted Channels</h5>
            <p class="text-muted small">Check channels to mute them</p>

            @foreach (var channel in AllChannels)
            {
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="ch-@channel"
                           checked="@MutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="ch-@channel">#@channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert alert-success mt-3">@_statusMessage</div>
        }
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedChannels = new();
    private List<string> AllChannels = new();
    private bool _initialized;
    private string? _statusMessage;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            AllChannels = new List<string>(Prefs.MutedChannels);
            MutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            MutedChannels.Add(channel);
        else
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(
            EmailNotifications,
            PushNotifications,
            WeeklyDigest,
            MutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _statusMessage = "✓ Notification preferences saved!";
    }
}

@namespace sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Components.Pages.Settings
@using sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Services

<div class="section-panel">
    <h3>Security</h3>
    <p class="text-muted">Manage your account security</p>
    <hr />

    @if (Settings is not null)
    {
        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer;" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <strong>Change Password</strong>
                <span>@(_passwordExpanded ? "▲" : "▼")</span>
            </div>
            @if (_passwordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger">@_passwordError</div>
                    }
                    @if (!string.IsNullOrEmpty(_passwordSuccess))
                    {
                        <div class="alert alert-success">@_passwordSuccess</div>
                    }

                    <button class="btn btn-warning" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                        @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    @if (Settings.LastPasswordChange.HasValue)
                    {
                        <div class="text-muted small mt-1">
                            Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </div>
                    }
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox"
                           checked="@_twoFactorEnabled"
                           @onchange="Toggle2FA" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card mb-4">
            <div class="card-header">
                <strong>Active Sessions</strong>
            </div>
            <div class="card-body p-0">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != Settings.Sessions.FirstOrDefault()?.Id)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-primary">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop show"></div>
            <div class="modal d-block" tabindex="-1">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on
                            <strong>@_sessionToRevoke.Device</strong>
                            from <strong>@_sessionToRevoke.Location</strong>?</p>
                            <p class="text-muted small">This will sign the user out of that device immediately.</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            _twoFactorEnabled = Settings.TwoFactorEnabled;
            _initialized = true;
        }
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "✓ Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
        await OnToggle2FA.InvokeAsync(_twoFactorEnabled);
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

