@namespace sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Components.Pages.Settings
@using sv_3bc3ac502cc44cbe9a23f2049b7c14a0.Services

<div class="section-panel">
    <h3>Appearance</h3>
    <p class="text-muted">Customize the look and feel</p>
    <hr />

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="theme-@theme" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="fs-@size" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;"
                            @bind="Language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@CompactMode"
                               @onchange="e => CompactMode = (bool)(e.Value ?? false)" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

                @if (!string.IsNullOrEmpty(_statusMessage))
                {
                    <div class="alert alert-success mt-3">@_statusMessage</div>
                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <h5>Preview</h5>
                <div class="preview-box @GetPreviewThemeClass()" style="@GetPreviewFontStyle()">
                    <div class="preview-header">
                        <strong>Sample Card</strong>
                    </div>
                    <div class="preview-body" style="@(CompactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                        <p style="margin-bottom: 0.5rem;">This is how your content will look.</p>
                        <p class="preview-muted">Language: @Language</p>
                        <div class="d-flex gap-2 mt-2">
                            <span class="preview-btn">Button</span>
                            <span class="preview-btn preview-btn-outline">Cancel</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private bool _initialized;
    private string? _statusMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "✓ Appearance settings saved!";
    }

    private string GetPreviewThemeClass() => Theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
